CREATE TABLE iview_dashboard_folder (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, folder_name VARCHAR(100) NOT NULL, parent_id BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_iview_dashboard_folder_parent FOREIGN KEY (parent_id) REFERENCES iview_dashboard_folder(id) ON DELETE RESTRICT);
CREATE TABLE iview_dashboard (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, folder_id BIGINT, model_id BIGINT, dashboard_name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(500) NOT NULL DEFAULT '', content_json CLOB NOT NULL, dashboard_status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', published_snapshot_id BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_iview_dashboard_folder FOREIGN KEY(folder_id) REFERENCES iview_dashboard_folder(id) ON DELETE RESTRICT, CONSTRAINT fk_iview_dashboard_model FOREIGN KEY(model_id) REFERENCES iview_data_model(id) ON DELETE RESTRICT);
CREATE TABLE iview_dashboard_snapshot (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, dashboard_id BIGINT NOT NULL, snapshot_version INT NOT NULL, content_json CLOB NOT NULL, model_id BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_iview_dashboard_snapshot_dashboard FOREIGN KEY(dashboard_id) REFERENCES iview_dashboard(id) ON DELETE CASCADE, CONSTRAINT uq_iview_dashboard_snapshot_version UNIQUE(dashboard_id,snapshot_version));
ALTER TABLE iview_dashboard ADD CONSTRAINT fk_iview_dashboard_published_snapshot FOREIGN KEY(published_snapshot_id) REFERENCES iview_dashboard_snapshot(id) ON DELETE RESTRICT;
